SELECT mon,sum(CASE WHEN reason='damaged' THEN qty ELSE 0 END)::BIGINT AS damaged,sum(CASE WHEN reason='wrong_item' THEN qty ELSE 0 END)::BIGINT AS wrong_item,sum(CASE WHEN reason='unwanted' THEN qty ELSE 0 END)::BIGINT AS unwanted FROM (SELECT date_trunc('month',refunded_at AT TIME ZONE 'UTC')::DATE AS mon,reason,qty::BIGINT AS qty FROM returns WHERE status='refunded' AND refunded_at>=TIMESTAMPTZ '2024-01-01 00:00:00+00' AND refunded_at<TIMESTAMPTZ '2025-01-01 00:00:00+00') r GROUP BY mon ORDER BY mon;
